#company#company .exact-insights-heading,#points#points .exact-insights-heading,#founder#founder .exact-insights-heading,#experience#experience .exact-insights-heading,#network#network .exact-insights-heading,#capabilities#capabilities .exact-insights-heading{display:block!important;width:100%!important;max-width:760px!important;margin:0 0 24px 0!important;padding:0!important;text-align:left!important;box-sizing:border-box!important}
