pat=re.escape(start)+r'.*?'+re.escape(end)
if re.search(pat,text,re.S): text=re.sub(pat,css,text,count=1,flags=re.S)
else: text=text.replace('</head>','<style>'+css+'</style>\n</head>',1)
p.write_text(text,encoding='utf-8')

probe=r'''<script>setTimeout(function(){function s(e){return getComputedStyle(e)}function vis(sec){return [].slice.call(document.querySelectorAll(sec+' .exact-insights-heading')).find(function(e){var q=s(e),r=e.getBoundingClientRect();return q.display!=='none'&&q.visibility!=='hidden'&&r.width>0&&r.height>0})}var rk=document.querySelector('#insights .eyebrow'),rh=document.querySelector('#insights .insight-intro h2'),rl=document.querySelector('#insights .eyebrow span'),rks=s(rk),rhs=s(rh),rls=s(rl),out={};['company','points','founder','experience','network','capabilities'].forEach(function(id){var w=vis('#'+id),k=w&&w.querySelector('.heading-ref-row'),h=w&&w.querySelector('h2'),l=k&&k.querySelector(':scope>span');if(!w||!k||!h||!l){out[id]={ok:false,reason:'missing'};return}var ks=s(k),hs=s(h),ls=s(l);var K=['fontSize','fontWeight','lineHeight','letterSpacing','color','marginBottom','fontFamily'].every(function(x){return ks[x]===rks[x]}),H=['fontSize','fontWeight','lineHeight','letterSpacing','color','marginBottom','fontFamily'].every(function(x){return hs[x]===rhs[x]}),L=['width','height','background'].every(function(x){return ls[x]===rls[x]});var P=[s(w,'::before'),s(w,'::after'),s(k,'::before'),s(k,'::after')].every(function(x){return x.content==='none'||x.display==='none'});var kr=k.getBoundingClientRect(),hr=h.getBoundingClientRect();var A=ks.textAlign==='left'&&hs.textAlign==='left'&&Math.abs(kr.left-hr.left)<1;out[id]={ok:K&&H&&L&&P&&A,K:K,H:H,L:L,noSquare:P,left:A,kicker:{mb:ks.marginBottom,fs:ks.fontSize},heading:{fs:hs.fontSize,fw:hs.fontWeight,ls:hs.letterSpacing,mb:hs.marginBottom},line:{w:ls.width,h:ls.height}}});document.body.setAttribute('data-final-audit',encodeURIComponent(JSON.stringify(out)))},1800)</script>'''
v=text.replace('</body>',probe+'\n</body>',1); vp=Path('.final-audit.html');vp.write_text(v,encoding='utf-8')
chrome='/usr/bin/google-chrome'
if not Path(chrome).exists(): chrome='/usr/bin/chromium'
for width in (1280,390):
 r=subprocess.run([chrome,'--headless=new','--no-sandbox','--disable-gpu','--allow-file-access-from-files','--virtual-time-budget=6500',f'--window-size={width},1200','--dump-dom',vp.resolve().as_uri()],capture_output=True,text=True)
 m=re.search(r'data-final-audit="([^"]+)"',r.stdout)
 if not m: raise SystemExit('audit missing '+str(width))
 d=json.loads(unquote(html.unescape(m.group(1)))); print('FINAL',width,json.dumps(d,ensure_ascii=False)); bad=[k for k,x in d.items() if not x.get('ok')]
 if bad: raise SystemExit('final mismatches '+str(width)+': '+','.join(bad))
vp.unlink(missing_ok=True); print('FINAL SIX EXACT MATCH PASSED')
